    SELECT 'matorrales-termomediterraneos-y-5330', '5330', 'Matorrales termomediterráneos y pre-estépicos', 'Matorral', 'El matorral de las zonas más cálidas y secas, allí donde prácticamente no hiela: palmito, espino negro, lentisco, cornicales, bojas, albaidas y esparto sobre laderas pedregosas y llanos soleados. Es un matorral abierto, con suelo desnudo a la vista entre mata y mata, y con muchas especies compartidas con el norte de África. Aguanta sequías de meses y rebrota en cuanto llueve.', 0, 38.431112, -1.13242, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.222076,38.424001],[-1.222048,38.423874],[-1.221918,38.423796],[-1.221773,38.423758],[-1.221656,38.423715],[-1.221525,38.423713],[-1.22135,38.423733],[-1.221203,38.423826],[-1.221101,38.423919],[-1.221027,38.424008],[-1.220938,38.424087],[-1.22085,38.424167],[-1.220747,38.42426],[-1.220645,38.424326],[-1.220557,38.424406],[-1.220424,38.42449],[-1.220264,38.424532],[-1.220088,38.424588],[-1.219884,38.424644],[-1.219694,38.424704],[-1.219563,38.424679],[-1.219446,38.424677],[-1.219301,38.424644],[-1.219156,38.424605],[-1.218995,38.424585],[-1.218909,38.424516],[-1.218764,38.424446],[-1.218692,38.424364],[-1.218634,38.424282],[-1.218606,38.424183],[-1.218607,38.424056],[-1.218609,38.423908],[-1.21864,38.423755],[-1.218699,38.423585],[-1.21876,38.423423],[-1.218848,38.423299],[-1.218922,38.42316],[-1.218996,38.423049],[-1.219041,38.42291],[-1.219043,38.422774],[-1.219044,38.422635],[-1.219016,38.422508],[-1.218973,38.422395],[-1.218916,38.422277],[-1.218801,38.422163],[-1.218641,38.422138],[-1.218437,38.422116],[-1.218262,38.422114],[-1.218072,38.422115],[-1.217898,38.422113],[-1.217767,38.422111],[-1.217563,38.422112],[-1.217402,38.422132],[-1.217286,38.422135],[-1.217155,38.422133],[-1.216965,38.42218],[-1.216834,38.422178],[-1.216673,38.422211],[-1.216468,38.422312],[-1.216365,38.422414],[-1.216306,38.422508],[-1.216203,38.422623],[-1.216114,38.422725],[-1.216026,38.422805],[-1.215924,38.422849],[