    SELECT 'encinares-de-quercus-9340', '9340', 'Encinares de Quercus ilex y Quercus rotundifolia', 'Bosque', 'El bosque mediterráneo por excelencia: encinares y carrascales de hoja dura, pequeña y perenne, que aguantan tanto el calor del verano como las heladas del interior. Bajo los árboles crece un sotobosque denso de coscoja, lentisco, madroño, enebros y aromáticas, y en el suelo la bellota sostiene en otoño a jabalíes, palomas y arrendajos. Aclarado por el ser humano durante siglos, ha dado lugar a las dehesas.', 0, 38.435326, -1.150682, '#6b8e23', '{"type":"Polygon","coordinates":[[[-1.185622,38.423406],[-1.18551,38.423327],[-1.185349,38.423235],[-1.185189,38.423192],[-1.185072,38.423145],[-1.184941,38.423111],[-1.184795,38.423042],[-1.184678,38.422999],[-1.184547,38.422966],[-1.184415,38.422905],[-1.184284,38.422885],[-1.184168,38.422852],[-1.184051,38.422805],[-1.183949,38.422758],[-1.183832,38.422716],[-1.183701,38.42266],[-1.183569,38.422613],[-1.183452,38.422566],[-1.183336,38.422532],[-1.183205,38.422512],[-1.183044,38.422478],[-1.182898,38.422453],[-1.182723,38.42241],[-1.182578,38.422363],[-1.182417,38.42232],[-1.1823,38.422286],[-1.182169,38.422262],[-1.182038,38.422264],[-1.181907,38.422204],[-1.181688,38.422115],[-1.181571,38.422059],[-1.18144,38.42198],[-1.181352,38.421911],[-1.18125,38.421842],[-1.181177,38.421751],[-1.181074,38.421646],[-1.180986,38.421559],[-1.180913,38.421467],[-1.180855,38.421385],[-1.180752,38.421294],[-1.180665,38.421216],[-1.180577,38.421133],[-1.180475,38.421042],[-1.180376,38.420954],[-1.180214,38.420902],[-1.179779,38.420679],[-1.179642,38.420655],[-1.179526,38.420693],[-1.179439,38.42076],[-1.179323,38.420852],[-1.179206,38.420945],[-1.179017,38.420978],[-1.178872,38.420922],[-1.178725,38.420879],[-1.17858,38.420832],[-1.178463,38.420776],[-1.178346,38.420707],[-1.178273,38.420629],[-1.178185,38.420537],[-1.178127,38.420433],[-1.178053,38.420306],[-1.177994,38.420206],[-1.177951,38.420092],[-1.177892,38.419997],[-1.1778