    SELECT 'pendientes-rocosas-calcicolas-8210', '8210', 'Pendientes rocosas calcícolas con vegetación casmofítica', 'Roquedos', 'Paredes y cortados de roca caliza en los que la vegetación no vive sobre el suelo, sino dentro de las fisuras. Son plantas de raíz larguísima y crecimiento lentísimo, agarradas a la grieta, que aprovechan el agua que escurre por la pared. Los roquedos han quedado a salvo del arado y del ganado durante milenios, y por eso concentran una proporción altísima de especies que no existen en ningún otro lugar.', 0, 38.423477, -1.153133, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.211461,38.41322],[-1.20982,38.412045],[-1.210157,38.410258],[-1.210074,38.410229],[-1.209899,38.410209],[-1.209783,38.410184],[-1.209638,38.410146],[-1.209492,38.410148],[-1.209375,38.410146],[-1.20923,38.410144],[-1.209084,38.410169],[-1.208924,38.410167],[-1.208763,38.410191],[-1.208646,38.410225],[-1.208486,38.410246],[-1.208311,38.410247],[-1.208165,38.410245],[-1.208005,38.410243],[-1.207816,38.410208],[-1.207656,38.410174],[-1.207511,38.410127],[-1.207395,38.41008],[-1.207294,38.409975],[-1.207222,38.409875],[-1.207208,38.40978],[-1.207136,38.40968],[-1.207079,38.409598],[-1.207022,38.409507],[-1.206935,38.409438],[-1.206834,38.409342],[-1.206718,38.409308],[-1.206601,38.409261],[-1.206456,38.409264],[-1.206267,38.409202],[-1.206107,38.409191],[-1.205991,38.409189],[-1.205859,38.409192],[-1.205714,38.409189],[-1.205568,38.409187],[-1.205394,38.409189],[-1.205101,38.409234],[-1.20497,38.409232],[-1.204854,38.409253],[-1.204679,38.409255],[-1.204474,38.409355],[-1.204284,38.409402],[-1.204138,38.409458],[-1.203977,38.409501],[-1.203874,38.409558],[-1.203684,38.409649],[-1.203538,38.409719],[-1.20342,38.409798],[-1.203304,38.409842],[-1.203171,38.409921],[-1.202966,38.410048],[-1.20279,38.410163],[-1.202658,38.410278],[-1.202511,38.410357],[-1.20235,38.410458],[-1.202189,38.410573],[-1.201998,38.410718],[-1.201807,38.410846],[-1.201631,38.410947],[-1.2014