    SELECT 'vegetacion-gipsicola-iberica-1520', '1520', 'Vegetación gipsícola ibérica (Gypsophiletalia)', 'Matorral', 'Matorral bajo y ralo que crece únicamente sobre yeso, un suelo blanquecino que forma costra y en el que casi ninguna otra planta prospera. Las que lo consiguen están especializadas en ese sustrato y muchas no viven en ningún otro sitio, de modo que cada afloramiento de yeso tiene su propia flora. No se recupera: al roturar o extraer el yeso desaparecen a la vez el suelo y lo que crecía sobre él.', 1, 38.437096, -1.229132, '#9acd32', '{"type":"Polygon","coordinates":[[[-1.248276,38.446343],[-1.248224,38.446],[-1.248114,38.445574],[-1.24799,38.445136],[-1.247819,38.444849],[-1.247604,38.444666],[-1.247387,38.44455],[-1.247229,38.444421],[-1.247042,38.444292],[-1.246796,38.44414],[-1.246637,38.444084],[-1.246405,38.444035],[-1.2461,38.443999],[-1.245882,38.443982],[-1.245736,38.443971],[-1.245461,38.443877],[-1.245274,38.443761],[-1.245145,38.443656],[-1.245001,38.443473],[-1.244888,38.443309],[-1.244777,38.442965],[-1.244735,38.442875],[-1.244723,38.44269],[-1.244641,38.442337],[-1.244645,38.442062],[-1.244564,38.441714],[-1.244436,38.441487],[-1.244264,38.441322],[-1.244047,38.44122],[-1.243787,38.441112],[-1.243555,38.441064],[-1.243423,38.441066],[-1.243162,38.441026],[-1.24293,38.440946],[-1.242655,38.440852],[-1.242366,38.440654],[-1.242137,38.440434],[-1.24198,38.440238],[-1.241508,38.439695],[-1.241208,38.43937],[-1.24105,38.43921],[-1.240879,38.438978],[-1.240723,38.438714],[-1.240639,38.438506],[-1.240556,38.438266],[-1.240501,38.43799],[-1.240494,38.437535],[-1.240542,38.437238],[-1.240708,38.436907],[-1.241063,38.436521],[-1.24133,38.436259],[-1.24161,38.436011],[-1.241834,38.435703],[-1.241866,38.435451],[-1.24183,38.434982],[-1.241763,38.43463],[-1.241576,38.434442],[-1.241376,38.434245],[-1.241233,38.434095],[-1.241146,38.434017],[-1.240943,38.433978],[-1.240752,38.434078],[-1.240605,38.434193],[-1.240485,38.434421],[-1.240451,38.434732]