    SELECT 'prados-calcareos-carsticos-6110', '6110', 'Prados calcáreos cársticos o basófilos del Alysso-Sedion albi', 'Pastos', 'Pastos abiertos sobre repisas y lanchas de roca caliza con apenas un dedo de tierra encima. Ahí solo prosperan plantas crasas de hojas gordas, como las uñas de gato (Sedum), y hierbas anuales minúsculas que nacen, florecen y mueren entre febrero y mayo. Ocupa superficies muy pequeñas y depende de que el suelo siga siendo escaso: en cuanto se acumula tierra, otras plantas lo desplazan.', 1, 38.432468, -1.160842, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.179311,38.44662],[-1.179201,38.446032],[-1.178846,38.445743],[-1.178435,38.445534],[-1.178095,38.445456],[-1.177231,38.445281],[-1.177141,38.445279],[-1.177058,38.44531],[-1.177001,38.445363],[-1.17698,38.44543],[-1.176999,38.445502],[-1.177056,38.445557],[-1.177131,38.445586],[-1.177992,38.445761],[-1.178266,38.445824],[-1.178589,38.445991],[-1.178824,38.44618],[-1.178903,38.446604],[-1.17882,38.446887],[-1.178579,38.447221],[-1.178128,38.447543],[-1.177638,38.447882],[-1.176905,38.448087],[-1.175587,38.448265],[-1.174075,38.448246],[-1.173993,38.448258],[-1.17392,38.448302],[-1.173878,38.448364],[-1.173874,38.448432],[-1.173911,38.4485],[-1.17398,38.448546],[-1.174068,38.448561],[-1.175618,38.448581],[-1.177008,38.448395],[-1.177845,38.448156],[-1.178394,38.447781],[-1.178896,38.447424],[-1.179199,38.447001],[-1.179311,38.44662]]],[[[-1.175645,38.424769],[-1.175546,38.423943],[-1.175042,38.423291],[-1.174484,38.422976],[-1.173782,38.422866],[-1.173338,38.422944],[-1.173234,38.422871],[-1.173162,38.422838],[-1.173072,38.422828],[-1.172988,38.422853],[-1.172926,38.422907],[-1.172917,38.422929],[-1.171796,38.422591],[-1.170483,38.42249],[-1.169534,38.422462],[-1.168632,38.422511],[-1.16786,38.42262],[-1.16728,38.422845],[-1.166703,38.423237],[-1.166062,38.423299],[-1.165685,38.423487],[-1.165342,38.423959],[-1.164684,38.423872],[-1.164128,38.423693],[-1.163338,38.423446],[-1.16