    SELECT 'bosques-endemicos-de-9560', '9560', 'Bosques endémicos de Juniperus spp.', 'Bosque', 'Bosques abiertos y luminosos de sabinas y enebros arbóreos (Juniperus), con los árboles separados entre sí y un pasto o matorral bajo entre ellos. Se instalan donde el frío, el viento o la falta de suelo impiden que se cierre un bosque, desde páramos continentales hasta laderas costeras. Crecen extraordinariamente despacio y son muy longevos, así que un sabinar arrasado no vuelve en una vida humana.', 1, 38.432557, -1.160709, '#9acd32', '{"type":"MultiPolygon","coordinates":[[[[-1.179311,38.44662],[-1.179201,38.446032],[-1.178846,38.445743],[-1.178435,38.445534],[-1.178095,38.445456],[-1.177231,38.445281],[-1.177141,38.445279],[-1.177058,38.44531],[-1.177001,38.445363],[-1.17698,38.44543],[-1.176999,38.445502],[-1.177056,38.445557],[-1.177131,38.445586],[-1.177992,38.445761],[-1.178266,38.445824],[-1.178589,38.445991],[-1.178824,38.44618],[-1.178903,38.446604],[-1.17882,38.446887],[-1.178579,38.447221],[-1.178128,38.447543],[-1.177638,38.447882],[-1.176905,38.448087],[-1.175587,38.448265],[-1.174075,38.448246],[-1.173993,38.448258],[-1.17392,38.448302],[-1.173878,38.448364],[-1.173874,38.448432],[-1.173911,38.4485],[-1.17398,38.448546],[-1.174068,38.448561],[-1.175618,38.448581],[-1.177008,38.448395],[-1.177845,38.448156],[-1.178394,38.447781],[-1.178896,38.447424],[-1.179199,38.447001],[-1.179311,38.44662]]],[[[-1.175645,38.424769],[-1.175546,38.423943],[-1.175042,38.423291],[-1.174484,38.422976],[-1.173782,38.422866],[-1.173338,38.422944],[-1.174045,38.423447],[-1.174487,38.424219],[-1.174388,38.425042],[-1.17412,38.42566],[-1.17376,38.426177],[-1.172986,38.426944],[-1.172153,38.427441],[-1.171189,38.42779],[-1.17022,38.428122],[-1.169355,38.428469],[-1.168646,38.428652],[-1.168088,38.428738],[-1.167463,38.428872],[-1.166943,38.42917],[-1.166555,38.429493],[-1.165858,38.429753],[-1.165098,38.429957],[-1.164312,38.430116],[-1.163594,38.430046],[-1.162603,38.429868],[-1