    SELECT 'prados-alpinos-y-6170', '6170', 'Prados alpinos y subalpinos calcáreos', 'Pastos', 'Pastos de alta montaña sobre suelos calizos, por encima del límite del bosque, donde la nieve cubre el terreno buena parte del año. Son céspedes bajos, densos y muy diversos, con plantas de porte enano y flores desproporcionadamente grandes que florecen en cuanto se funde la nieve. El corto verano y el pastoreo tradicional han modelado juntos este paisaje.', 0, 38.432151, -1.160935, '#a0522d', '{"type":"Polygon","coordinates":[[[-1.175645,38.424769],[-1.175546,38.423943],[-1.175042,38.423291],[-1.174484,38.422976],[-1.173782,38.422866],[-1.173338,38.422944],[-1.173234,38.422871],[-1.173162,38.422838],[-1.173072,38.422828],[-1.172988,38.422853],[-1.172926,38.422907],[-1.172917,38.422929],[-1.171796,38.422591],[-1.170483,38.42249],[-1.169534,38.422462],[-1.168632,38.422511],[-1.16786,38.42262],[-1.16728,38.422845],[-1.166703,38.423237],[-1.166062,38.423299],[-1.165685,38.423487],[-1.165342,38.423959],[-1.164684,38.423872],[-1.164128,38.423693],[-1.163338,38.423446],[-1.162783,38.423415],[-1.162276,38.423645],[-1.161916,38.424018],[-1.161543,38.424409],[-1.161005,38.424576],[-1.160612,38.424543],[-1.160174,38.424559],[-1.159769,38.424791],[-1.159322,38.425158],[-1.158743,38.425428],[-1.158016,38.425583],[-1.157302,38.425653],[-1.156804,38.425443],[-1.156293,38.425376],[-1.155948,38.425709],[-1.156024,38.426043],[-1.156276,38.426295],[-1.156324,38.426661],[-1.15608,38.426927],[-1.155353,38.427069],[-1.154147,38.427365],[-1.152299,38.427652],[-1.150038,38.428598],[-1.148795,38.429453],[-1.148861,38.430048],[-1.149098,38.430322],[-1.149407,38.430526],[-1.14986,38.430605],[-1.150515,38.430529],[-1.151517,38.430261],[-1.152491,38.430034],[-1.153004,38.430217],[-1.152805,38.430597],[-1.152344,38.430964],[-1.151896,38.43129],[-1.15107,38.431732],[-1.150101,38.432276],[-1.149102,38.432823],[-1.148045,38.433415],[-1.147104,38.433904],[-1.14635,38.43423],[-1.145409,38.434684],[-1.1444