    SELECT 'Conejo', 'Oryctolagus cuniculus', 'fauna', 'Mamífero', 'Matorral termomediterráneo semiárido', 'EN', 'Lagomorfo excavador que vive en madrigueras coloniales; pieza clave del ecosistema mediterráneo como presa de águila perdicera, búho real y carnívoros.', NULL, 'Excava madrigueras coloniales; Presa clave de rapaces; Activo al amanecer y atardecer', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Oryctolagus_cuniculus_Tasmania_2.jpg?width=1280', 'JJ Harrison (https://www.jjharrison.com.au/) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-15); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Mammalia', 'Lagomorpha', 'Leporidae', 'Oryctolagus', 'EN (Lista Roja mundial UICN 2019: En Peligro por declive en su área nativa)', 'No incluida en el LESRPE; especie cinegética y presa clave del ecosistema mediterráneo', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11109, 2436940, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rana común', 'Pelophylax perezi', 'fauna', 'Anfibio', 'Charcas, balsas, acequias y tramos remansados con vegetación', 'LC', 'La rana verde ibérica, la más común y adaptable de nuestros anfibios: coloniza desde ramblas y balsas de riego hasta fuentes urbanas. Su canto es un cacareo entrecortado que forma coros al atardecer. Salta al agua al menor movimiento en la orilla.', NULL, 'Línea clara a lo largo del centro del lomo en muchos ejemplares; Canto entrecortado, como una risa o un cacareo; Salta al agua desde la orilla al notar movimiento', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pelophylax_perezi_by-dpc.jpg?width=1280', 'David Perez (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro de los polígonos de hábitat del espacio (2 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Amphibia', 'Anura', 'Ranidae', 'Pelophylax', 'LC (Preocupación menor) (evaluación UICN 2022)', 'Anexo VI (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007); UICN España: LC (Preocupación menor) (2002)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11964, 2426658, NULL, NULL, NULL
