    SELECT 'Ceje', 'Helianthemum cinereum', 'flora', 'Mata', 'Crece en tomillares y matorrales sobre suelos secos calizos, dolomíticos o yesosos, hasta 2400 m', 'No catalogada', 'Perenne sufruticosa, de 4-30 cm, con tallos ascendentes o erectos, redondeados, de tomentosos a glabros. Hojas con limbo de 4-20 x 2-10 mm, pecioladas, de ovadas a oblongo- lanceoladas, opuestas, a veces las superiores alternas, con envés generalmente peloso o tomentoso, las inferiores sin estípulas, las superiores con estípulas foliáceas. Pétalos de 3-6 mm, pequeños, mayores que el cáliz, amarillos. Cápsula de 3-5 mm, ovoide-elipsoidal, glabra o pelosa en el ápice. Semillas pardo-amarillentas. Especie de la que se han considerado cuatro subespecies, tres de ellas endemismos españoles.', NULL, NULL, 'Enero a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_cinereum_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha, que la cita como «Helianthemum cinereum subsp. rotundifolium»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 4971, 7331381, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ceje', 'Helianthemum marifolium', 'flora', 'Mata', 'Crece en matorrales secos sobre sustratos calizos o dolomíticos, hasta 1900 m', 'No catalogada', 'Perenne sufruticosa, de 5-35 cm, con cepa de ramas ascendentes o erectas y tallos de tomentosos o setosos a glabros. Hojas con limbo de 2,5-23 x 1,2-15 mm, con pecíolo de 0-3 mm, la mayoría opuestas, gruesas, algo carnosas sin estípulas, de ovadas a elípticas, a veces acorazonadas, blanco-tomentosas en el envés. Cimas simples con pocas flores. Pétalos 5, de 4-10 mm, amarillos. Fruto en cápsula de 3-5 mm, ovoide-elipsoidal, glabra o pelosa arriba. Dada su gran variabilidad, se han considerado seis subespecies, cuatro de ellas endemismos españoles.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Octubre a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_marifolium_-_Saint-Hilaire.jpg?width=1280', 'autor no indicado (Public domain) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (7 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha, que la cita como «Helianthemum marifolium subsp. marifolium»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 5080, 7331330, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lastón', 'Helictotrichon filifolium', 'flora', 'Gramínea', NULL, 'LC', NULL, NULL, NULL, 'Marzo, abril, mayo, junio, julio, septiembre, octubre, noviembre, diciembre, enero', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helictotrichon_filifolium.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 2 ocurrencias dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Helictotrichon', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10044, 4153003, NULL, NULL, NULL
