    SELECT 'Tomillo', 'Artemisia campestris', 'flora', 'Arbusto', 'Vive en formación de matorral sobre sustratos nitrificados, en bordes de camino y baldíos, en lugares secos y soleados, hasta 2300 m', 'No catalogada', 'Arbustillo hasta de 0,8 m, de base leñosa, con tallos divididos y hojas basales numerosas, dos o tres veces divididas, con segmentos filiformes, las de arriba enteras. Capítulos dispuestos en panícula terminal, numerosos, de 1-2 mm de anchura, algo alargados, muy pequeños, con florecillas minúsculas, amarillentas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Artemisia_campestris_11.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha, que la cita como «Artemisia campestres subsp. glutinosa» (la tabla escribe «campestres»; el epíteto al uso es campestris); EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Artemisia', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10343, 3121461, NULL, NULL, NULL
    UNION ALL
    SELECT 'Abrótano hembra', 'Artemisia herba-alba', 'flora', NULL, 'Vive en lugares soleados, como arvense y ruderal, con frecuencia sobre sustratos salobres, hasta 1500 m', 'No catalogada', 'Planta perenne de base leñosa, hasta de 60 cm, con tallos numerosos, pelosos, blanquecinos, y hojas hasta de 1 cm, divididas en segmentos algo carnosos y formando fascículos axilares. Capítulos en panícula terminal, de 3 mm de diámetro, con brácteas ovadas, en general glandulíferas. Florecillas amarillentas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', NULL, NULL, NULL, NULL, 3, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Artemisia', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 9919, 3120848, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gamoncillo', 'Asphodelus fistulosus', 'flora', 'Hierba', 'Pastizales secos, bordes de camino y terrenos removidos', 'LC', 'Gamón pequeño de hojas cilíndricas y huecas —de ahí su nombre— que salen todas de la base. Levanta un tallo ramificado con flores blancas de nervio rosado, que se abren de forma escalonada durante semanas. Es una de las primeras plantas en colonizar cunetas y baldíos.', NULL, 'Hojas finas, cilíndricas y huecas por dentro; Flores blancas con una raya rosa en cada pétalo; Cápsulas redondas y pequeñas al fructificar', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/A._fistulosus-flor-2.JPG?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asphodelaceae', 'Asphodelus', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2521, 2778437, NULL, NULL, NULL
    UNION ALL
