    SELECT 'Lastón', 'Brachypodium retusum', 'flora', 'Gramínea', 'Pastizales, claros de matorral y ribazos sobre suelos calizos', 'LC', 'Gramínea perenne y rizomatosa que forma céspedes extensos en los claros del matorral mediterráneo. Sus hojas son cortas, rígidas y de punta roma. Es de las plantas que más rápido rebrota tras un incendio, gracias a sus rizomas subterráneos.', NULL, 'Céspedes extensos y bajos, no matas aisladas; Hojas cortas y rígidas, de punta redondeada; Espiguillas alineadas a un lado de un eje rígido', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_espiga_seca.jpg?width=1280', 'Pere prlpz (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Brachypodium', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 9931, 5676053, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mijo del sol', 'Buglossoides arvensis', 'flora', NULL, NULL, 'No catalogada', NULL, NULL, NULL, 'Febrero a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Buglossoides_arvensis_300406.jpg?width=1280', 'Bernd Haynold (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 0, 'Sin descripción: ninguna fuente publica texto para este taxón. Oculta hasta redactarla.', 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha, que la cita como «Buglossoides arvensis subsp. arvensis»; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Boraginales', 'Boraginaceae', 'Buglossoides', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 2812, 2925901, NULL, NULL, NULL
