    SELECT 'Cuchareta', 'Carrichtera annua', 'flora', 'Hierba', 'Pastizales anuales, eriales y suelos margosos removidos en clima árido', 'No catalogada', 'Crucífera anual de flores blanquecinas con nervios violáceos, inconfundible por su fruto: una vainita corta rematada por una lengüeta plana y curvada que recuerda a una cuchara. Los frutos secos persisten sobre la planta y son la mejor pista para identificarla.', NULL, 'Frutos con una pala plana en el extremo, como cucharillas; Hojas muy divididas, de segmentos estrechos; Planta anual pelosa, de pocos decímetros, en suelo pelado', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carrichtera_annua2.JPG?width=1280', 'Flora y Vegetación de Lanzarote (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Carrichtera', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 3176, 5375285, NULL, NULL, NULL
    UNION ALL
    SELECT 'Centaurea', 'Centaurea aspera', 'flora', 'Hierba', 'Vive en lugares alterados como márgenes de caminos o eriales, hasta 1500 m', 'No catalogada', 'Hierba perenne, hasta de 80 cm, inerme, lanuginosa, con tallos ramificados arriba. Hojas basales pecioladas, de enteras a pinnnatipartidas, con lóbulos acabados en espínulas no punzantes, las medias sentadas, elípticas o lineares. Capítulos en panículas corimbiformes, glabros, con involucro de 10-17 x 4,5-12 mm, ovoide, con cinco filas de brácteas imbricadas, hasta con cinco espinas amarillentas finas hasta de 3 mm. Flores liguladas y tubulosas, blanquecinas en la base y coloreadas arriba. Aquenios 3,5-5 mm, oblongo-ovoides, amarillentos, con vilano hasta de 3 mm, doble.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Centaurea_aspera.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Centaurea', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 3214, 3128166, NULL, NULL, NULL
