    SELECT 'Chupera', 'Cytinus hypocistis', 'flora', 'Hierba', 'Es silicícola y vive sobre granitos, pizarras, cuarcitas, en terraplenes, claros de bosque, hasta 2900 m', 'No catalogada', 'Planta herbácea perenne o bienal, a veces leñosa en la base, de 0,5-1 m, con pelos glandulíferos. Hojas alternas, las inferiores de 5-20 x 1,5-10 cm, atenuadas en el pecíolo de 1,5-6,5 cm, elípticas, crenuladas o dentadas. Inflorescencia en racimos de 15-70 cm; flores con cinco sépalos algo desiguales. Corola de 3-4,5 cm, acampanada, con tubo 1,5-2 veces más largo que ancho, rosado-púrpura, con grandes manchas púrpuras por dentro; labio superior entero o escotado, el inferior con tres lóbulos anchos, redondeados. Fruto en cápsula de 9-15 x 6-10 mm, ovoideo, que acaba en un largo estilo.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cytinus_hypocistis.jpg?width=1280', 'Bouba at French Wikipedia (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cytinaceae', 'Cytinus', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 3805, 7279691, NULL, NULL, NULL
    UNION ALL
    SELECT 'Altrobisca', 'Daphne gnidium', 'flora', 'Arbusto', 'Vive en encinares, coscojares, alcornocales y pinares o a veces en formaciones de matorrales, sobre cualquier tipo de sustrato, hasta 1400 m', 'No catalogada', 'Arbusto 0,5-2 m, ramificado, con tallos muy foliosos. Hojas hasta de 4 cm, lanceoladas 5-10 cm, agudas. Inflorescencias terminales, con flores de unos 6 mm, con un tubo, cuatro pétalos y cuatro estambres que se ven dentro del tubo y otros cuatro que nacen más abajo. Fruto de 7 mm, globoso, carnoso, color rojo, con una semilla.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Daphne_gnidium3.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Thymelaeaceae', 'Daphne', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 3964, 7311306, NULL, NULL, NULL
