    SELECT 'Esparto', 'Macrochloa tenacissima', 'flora', 'Gramínea', 'Laderas secas y llanos sobre suelos pobres; forma espartales extensos', 'VU', 'El esparto, nombrado también como Stipa tenacissima, forma matas densas y duraderas que dan nombre a los espartales, uno de los paisajes característicos del sureste ibérico. Sus hojas se enrollan sobre sí mismas en los días secos para perder menos agua y se abren tras la lluvia. Durante siglos se recolectó para hacer cuerdas, esteras y alpargatas.', NULL, 'Matas grandes y compactas de hojas duras enrolladas; Las hojas se abren tras la lluvia y se enrollan al secar; Espigas altas y plateadas a final de primavera', 'Primavera (espigado)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_tenacissima.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Macrochloa', 'VU (Vulnerable) (evaluación UICN 2018)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 27376, 4127897, NULL, NULL, NULL
    UNION ALL
    SELECT 'Manrubio pinchoso', 'Marrubium alysson', 'flora', 'Hierba', 'Vive sobre sustratos margosos y salinos o en lugares nitrificados, hasta 750 m', 'No catalogada', 'Hierba perenne hasta de 40 cm, con hojas de 1,7-4,2 x 0,9-2,1 cm, cuneadas o en forma de abanico, dentadas o lobuladas, con pecíolo largo, sobre todo las inferiores, cáliz con tubo de 5 mm y con cinco dientes rígidos hasta de 4 mm, triangulares, perpendiculares al tubo, y con corola que sobresale poco del cáliz, de color púrpura.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/M.alysson-2.JPG?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Marrubium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 6220, 3882151, NULL, NULL, NULL
