    SELECT 'Rabo de gato', 'Sideritis bourgaeana', 'flora', 'Mata aromática', 'Tomillares y matorral raso sobre suelos calizos secos', 'No catalogada', 'Rabogato de tallos blanquecinos y flores agrupadas en verticilos separados, característico del sureste ibérico. Es un taxón raro y poco fotografiado: como otras labiadas del grupo, se ha usado tradicionalmente en infusiones.', NULL, 'Tallos y hojas cubiertos de pelusa blanca; Flores en anillos bien separados a lo largo del tallo; Brácteas anchas y algo punzantes bajo cada verticilo', 'Primavera y verano', NULL, NULL, NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Sideritis', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8279, 3892179, NULL, NULL, NULL
    UNION ALL
    SELECT 'zahareña lanuda', 'Sideritis montana', 'flora', 'Hierba', 'Vive en pastizales de anuales sobre pedregales, preferentemente calcáreos, entre 350-1600 m', 'No catalogada', 'Hierba anual, de 2,5-30 cm, con tallos simples, foliosos abajo; hojas de 11-23 x 3-9 mm, lanceoladas o espatuladas, enteras o con dos a cuatro dientes, pelosas; inflorescencia en verticilastros con dos a seis flores cada uno, brácteas como las hojas; cáliz de 7-9,5 mm, con pelos sedosos, y cinco dientes de 3-4,5 mm; corola de 5 mm, de color amarillo anaranjado.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Abril a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/DSC_5621_Sideritis_montana_L._stani%C5%A1te.jpg?width=1280', 'Lalakmus (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Sideritis', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8342, 2926688, NULL, NULL, NULL
