    SELECT 'Silene mellifera', 'Silene mellifera', 'flora', 'Hierba', 'Roquedos, taludes y claros de matorral sobre suelos calizos', 'No catalogada', 'Silene de flores blancas cuyos pétalos se abren al atardecer y desprenden un perfume dulce e intenso que atrae a polillas nocturnas. El cáliz es un tubo alargado con venas marcadas. De día las flores suelen aparecer mustias y cerradas.', NULL, 'Flores blancas que abren al anochecer y huelen intensamente; Cáliz tubular con venas bien marcadas; De día las flores parecen marchitas', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Silene_mellifera_Enfoque_2012-05-27_Robledillo_SierraMadrona.jpg?width=1280', 'Javier martin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Caryophyllaceae', 'Silene', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8413, 7267618, NULL, NULL, NULL
    UNION ALL
    SELECT 'Alcadicea', 'Silene vulgaris', 'flora', 'Hierba', 'En general en medios alterados por la acción humana', 'LC', 'Planta de hasta 80 cm, herbácea vivaz, con cepa leñosa, multicaule, glabra o algo pelosa por abajo y a menudo de color azulado. Hojas hasta de 8 x 1,5 cm, de tamaño muy variable, simples, opuestas, las caulinares sésiles, de ovadas a lanceoladas, apiculadas. Flores grandes, pedunculadas, agrupadas en dicasios. Cáliz muy inflado, 10-17 mm, con 5 sépalos soldados con 20 nervios reticulados. Corola con 5 pétalos libres, blancos, profundamente hendidos por arriba, que sobresalen del cáliz 5-10 mm. Estambres largos, visibles. Fruto en cápsula, 6-12 x 6-8 mm, rodeada por el cáliz, globosa, acabada en 6 dientes, que contiene muchas semillas diminutas, 1-2 mm, rugosas, de forma arriñonada.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a julio', 'https://commons.wikimedia.org/wiki/Special:FilePath/0_Silene_vulgaris_-_Sil%C3%A8ne_enfl%C3%A9_-_Saint-Nicolas-de-V%C3%A9roce_(1).JPG?width=1280', 'Jean-Pol GRANDMONT (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Caryophyllaceae', 'Silene', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2015)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8375, 9172281, NULL, NULL, NULL
    UNION ALL
    SELECT 'Arbeana', 'Sisymbrium irio', 'flora', 'Hierba', 'Vive en campos de cultivo y bordes de caminos, hasta 1300 m', 'No catalogada', 'Hierba anual, de 15-75 cm, con hojas pinnatisectas de lóbulos lanceolados. Flores en racimos con muchas flores, las nuevas sobrepasadas por los frutos jóvenes, con cuatro sépalos de 2-2,5 mm y pétalos pequeños, de 2,5-3,5 mm, de color amarillo. Frutos de 2,5-5 cm, muy finos, con semillas minúsculas.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Diciembre a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sisymbrium_irio.jpg?width=1280', 'autor no indicado (Public domain) · Wikimedia Commons', NULL, NULL, 2, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Sisymbrium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8458, 3046851, NULL, NULL, NULL
    UNION ALL
    SELECT 'Hierba gusanera', 'Sisymbrium orientale', 'flora', 'Hierba', 'Vive en bordes de caminos y campos de cultivo', 'No catalogada', 'Hierba anual, de 10-80 cm, con un tallo poco ramificado. Hojas en roseta, pinnatipartidas con dos a cinco pares de lóbulos, las caulinares también hastadas. Inflorescencia en racimo con pocas flores. Sépalos de 4-5,5 mm y pétalos de 7-9 mm, de color amarillo intenso. Frutos de 5-10 cm, erecto-patentes, pelosos, con tres nervios bien marcados en las valvas. Semillas muy numerosas, de 1,1-1,4 mm.', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Marzo a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sisymbrium_orientale_%2B_S._loeselii_sl1.jpg?width=1280', 'Stefan.lefnaer (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro de los polígonos de hábitat del espacio (4 hábitats; barrido de 2026-08-15); Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Sisymbrium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 8462, 3046812, NULL, NULL, NULL
