    SELECT 'Alcaudón común', 'Lanius senator', 'fauna', 'Ave', 'Matorral termomediterráneo semiárido', 'Protegida (LESRPE)', 'Alcaudón estival de cabeza castaña que caza insectos desde posaderos en el matorral abierto, empalando presas en espinas a modo de despensa.', NULL, 'Capirote castaño rojizo; Caza desde posaderos; Estival de mayo a agosto', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lanius_senator01_new.jpg?width=1280', 'Lanius_senator01.jpg: chausinho derivative work: Bogbumper (talk) (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 5 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Laniidae', 'Lanius', 'LC (SPEC, en declive en Europa)', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12190, 2492867, NULL, NULL, NULL
    UNION ALL
    SELECT 'Reyezuelo listado', 'Regulus ignicapilla', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Se trata de una de las aves más diminutas de la avifauna europea. En un primer vistazo, aparece como un pájaro de aspecto general rechoncho, con tonalidades verdosas y cabeza adornada por un característico diseño de listas. Presenta el dorso verde brillante, en contraste con las alas oscuras, surcadas por dos bandas blanquecinas. Las partes inferiores son pálidas, aunque muestran ligeros tonos anaranjados en el pecho del macho. La especie posee un diseño cefálico característico en el que destaca el píleo naranja en los machos, o amarillo en las hembras, flanqueado por una banda negra y una marcada ceja blanca. Asimismo, luce una lista ocular negra y un semianillo blanco que circunda la parte inferior del ojo.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Firecrest93.JPG?width=1280', 'NAUMANN, NATURGESCHICHTE DER VÖGEL MITTELEUROPAS: Band II, Tafel 15… (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 5 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha, que la cita como «Regulus ignicapillus»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Regulidae', 'Regulus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11499, 6093527, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gavilán común', 'Accipiter nisus', 'fauna', 'Ave rapaz', 'Bosques mixtos de coníferas y frondosas.Sotos, grandes arbustos', 'Protegida (LESRPE)', 'Esta pequeña rapaz de hábitos forestales, larga cola y alas cortas y redondeadas presenta un acusado dimorfismo sexual invertido, por el cual las hembras resultan ostensiblemente más corpulentas que los machos; además, entre ambos sexos existen marcadas diferencias en cuanto al diseño del plumaje. El macho adulto tiene las partes superiores y el píleo de un color grisáceo bastante intenso, en tanto que las inferiores son pálidas con un fino barrado transversal y un tono rojizo que puede ser muy notorio, principalmente en las mejillas y los flancos; sobre el ojo luce una leve línea blanca a modo de ceja. Las patas son amarillas y con los largos tarsos sin emplumar. La hembra, mucho más pesada y robusta, posee un patrón de coloración dominado por los tonos pardogrisáceos en el dorso y el píleo, con las regiones inferiores blanquecinas, muy finamente barradas de pardo; la ceja es más grande y evidente que en su compañero. El plumaje de los jóvenes presenta las partes superiores parduzcas, con las plumas orladas de ante, y las inferiores blanquecinas y toscamente barradas de pardo rojizo. Sobre el ojo —que es amarillo— exhibe una marcada ceja. Visto en vuelo, el gavilán es un ave bastante pálida, en cuya silueta llama la atención una cola larga y de base estrecha. Normalmente, se lo observa volando velozmente a baja altura entre los árboles, aunque también puede elevarse y planear durante un tiempo sobre el dosel forestal.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Eurasian_Sparrowhawk_by_Steve_Ward.jpg?width=1280', 'Steve Ward (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Accipitriformes', 'Accipitridae', 'Accipiter', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11849, 2480637, NULL, NULL, NULL
    UNION ALL
    SELECT 'Bisbita común', 'Anthus pratensis', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Ave de aspecto poco llamativo y sin caracteres muy distintivos, similar al resto de bisbitas. Exhibe dorso pardo, un tanto verdoso al principio del otoño, con muchas estrías oscuras; vientre blanco sucio muy rayado; y flancos anaranjados en otoño, que se aclaran según avanza el invierno. Posee alas redondeadas, cola larga y con plumas externas blancas, pico fino, y patas finas, con la uña posterior larga y recta. La garganta es blanca, con una fina bigotera negra. Ambos sexos son iguales. Los jóvenes, cuando llegan a España, no se distinguen de los adultos. Este pájaro se observa casi siempre en el suelo y en grupo. Para diferenciarlo de otros bisbitas hay que atender a las fechas, a su voz, a su pequeño tamaño, y a detalles del plumaje como flancos con estrías más gruesas y dorso menos contrastado.', NULL, NULL, 'Octubre a abril', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthus_pratensis.jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Motacillidae', 'Anthus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12019, 2490266, NULL, NULL, NULL
    UNION ALL
    SELECT 'Búho real', 'Bubo bubo', 'fauna', 'Ave rapaz nocturna', 'Cortados rocosos, barrancos y laderas con matorral y zonas abiertas de caza', 'Interés especial', 'El mayor búho de Europa, con casi dos metros de envergadura, penachos de plumas erguidos sobre la cabeza y ojos de un naranja encendido. Caza conejos, ratas e incluso otras rapaces. Su canto es un «bu-bo» profundo que se propaga kilómetros por los barrancos en las noches de invierno.', NULL, 'Penachos de plumas erguidos a los lados de la cabeza; Ojos naranjas muy intensos; Canto grave y profundo en las noches de invierno', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Bubo_bubo_sibiricus_-_01.JPG?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Strigiformes', 'Strigidae', 'Bubo', 'LC', 'LESRPE; Directiva Aves 2009/147/CE, Anexo I; Reglamento CITES (CE) 338/97, Anexo A', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 10917, 5959092, NULL, NULL, NULL
    UNION ALL
    SELECT 'Avión común', 'Delichon urbicum', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Pequeña golondrina de aspecto compacto, negro azulada brillante por arriba y blanca por abajo, con límites netos entre colores. Posee alas largas y apuntadas y cola corta ahorquillada de color negro; pico corto, plano y negro; boca muy ancha, y patas cortas cubiertas de finas plumas blancas. Destaca su obispillo de color blanco, la única zona clara de las partes dorsales. Ambos sexos son iguales. Los jóvenes resultan menos contrastados, más parduzcos, sobre todo por abajo, con límites difusos entre partes negras y blancas, y con puntas blancas en las terciarias. Este pájaro suele observarse en vuelo y agrupado. Su vuelo es rápido y ágil, aunque menos que en la golondrina común, y a menudo se produce a mayor altura que en esta. Se posa con frecuencia, a veces en el suelo.', NULL, NULL, 'Febrero a octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Delichon_urbicum_-Iceland_-flying-8_(1).jpg?width=1280', 'Ómar Runólfsson (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha, que la cita como «Delichon urbica»; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Hirundinidae', 'Delichon', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12368, 2489214, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cogujada montesina', 'Galerida theklae', 'fauna', 'Ave', 'Matorral bajo, laderas pedregosas y eriales con vegetación rala', 'Protegida (LESRPE)', 'Cogujada de cresta puntiaguda, muy parecida a la común pero de pico más corto y grueso y con el pecho más nítidamente rayado. Prefiere el matorral y las laderas pedregosas, mientras que la común busca cultivos, caminos y bordes de pueblo.', NULL, 'Cresta alta y afilada, casi triangular; Pico más corto y romo que el de la cogujada común; Rayado del pecho bien definido, no difuminado', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Galerida_theklae_Madrid.jpg?width=1280', 'Adrian198cm (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 4 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Galerida', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12316, 9330514, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mochuelo europeo', 'Athene noctua', 'fauna', 'Ave', 'Matorral litoral y zonas abiertas con posaderos', 'Protegida (LESRPE)', 'Búho pequeño y rechoncho, de cabeza plana y ojos amarillos con un ceño que le da expresión severa. Es el más diurno de nuestros búhos: se ve posado en postes y ruinas a plena luz. Vuela con un ondulado marcado, a golpes de aleteo y planeo.', NULL, 'Cabeza plana y ancha, sin penachos; Cejas blancas marcadas que le dan aspecto ceñudo; Vuelo ondulado, a rachas de aleteo y planeo', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mochuelo_Com%C3%BAn_(_Athene_noctua_)(1).jpg?width=1280', 'Arturo Nikolai from Galicia, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Strigiformes', 'Strigidae', 'Athene', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Reglamento CITES (CE) 338/97, Anexo A', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11861, 2497266, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cuco', 'Cuculus canorus', 'fauna', 'Ave', 'Zonas arboladas de todo tipo.Bosques,linderos,bosquetes,cultivos,huertos frutales,piornales', 'Protegida (LESRPE)', 'Esta ave, de tamaño medio y aspecto estilizado, se caracteriza por poseer una larga cola y unas alas apuntadas, por lo que su silueta puede confundirse en vuelo con la de una pequeña rapaz, como el cernícalo vulgar o el gavilán. En la coloración del macho dominan los tonos grises, sobre todo en el dorso, la cabeza y el cuello. Por su parte, las regiones ventrales son blancas, pero finamente barreadas. La hembra puede lucir dos tipos de plumaje: uno grisáceo, muy parecido al del macho, y otro rojizo, bastante menos frecuente que el anterior. Los inmaduros se asemejan en parte a las hembras de fase rojiza, aunque tienen las plumas orladas de blanco y una característica mancha blanca en la nuca.', NULL, NULL, 'Marzo a junio', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cuckoo_(51169010335).jpg?width=1280', 'Andy Morffew from Itchen Abbas, Hampshire, UK (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Cuculiformes', 'Cuculidae', 'Cuculus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10952, 5231918, NULL, NULL, NULL
    UNION ALL
    SELECT 'Abejaruco europeo', 'Merops apiaster', 'fauna', 'Ave', 'Matorral termomediterráneo semiárido', 'Protegida (LESRPE)', 'Ave colorida y gregaria que caza abejas y libélulas en vuelo sobre espacios abiertos y cría en galerías excavadas en taludes terrosos.', NULL, 'Colorido inconfundible; Reclamo ''prruip'' en vuelo; Cría en taludes de rambla', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/%C5%9Eahl%C3%BBr-33.jpg?width=1280', 'Dûrzan cîrano (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Coraciiformes', 'Meropidae', 'Merops', 'LC', 'LESRPE (RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10738, 2475443, NULL, NULL, NULL
    UNION ALL
    SELECT 'Roquero solitario', 'Monticola solitarius', 'fauna', 'Ave', 'Acantilados mediterráneos con Limonium', 'Protegida (LESRPE)', 'Pájaro rupícola de plumaje azul pizarra en el macho, ligado a acantilados marinos y roquedos, donde canta desde cornisas destacadas.', NULL, 'Macho azul pizarra; Canta desde cornisas y cumbres; Acantilados y roquedos calcáreos', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Blue_rock_thrush_(male)_at_Gamla_Nature_Reserve.jpg?width=1280', 'Artemy Voikhansky (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial, RD 139/2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial, RD 139/2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Monticola', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial, RD 139/2011)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12226, 2490955, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lavandera blanca', 'Motacilla alba', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Pájaro estilizado de aspecto muy distintivo, con larga cola y tonos blancos, negros y grises. Exhibe dorso gris ceniza, vientre blanco, y alas negras y con bandas blancas cuando están plegadas. Posee cola larga y negra, con plumas externas blancas, y patas y pico negros. El patrón de la cabeza resulta muy contrastado, con la cara blanca rodeada arriba y abajo de negro. Luce un plumaje invernal similar, aunque el color negro en la cabeza está más reducido, y muestra garganta blanca y banda pectoral negra. La lavandera enlutada (M. a. yarrelli), de origen británico, presenta tonos negros en dorso y flancos. Ambos sexos son parecidos, pero la hembra tiene la nuca gris. Los jóvenes resultan más uniformes, sin negro en la cabeza y con banda pectoral grisácea. Un hábito destacado de esta ave es el continuo balanceo de la cola. En invierno se vuelve muy gregaria y se reúne en dormideros.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/White-Wagtail.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Motacillidae', 'Motacilla', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10648, 9687165, NULL, NULL, NULL
    UNION ALL
    SELECT 'Collalba negra', 'Oenanthe leucura', 'fauna', 'Ave', 'Matorral litoral, laderas secas y roquedos', 'Protegida (LESRPE)', 'La mayor de las collalbas, enteramente negra salvo el obispillo y la base de la cola, blancos. Vive en cortados y laderas rocosas, donde construye junto al nido una plataforma de piedrecitas que acarrea una a una. Su canto es potente y melodioso.', NULL, 'Cuerpo negro con obispillo blanco muy contrastado; «T» negra invertida en la cola blanca al volar; Montoncitos de piedrecitas junto a la grieta del nido', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Black_Wheatear%2C_Isla_Plana_3.jpg?width=1280', 'Andrew Thomas from Shrewsbury, UK (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Oenanthe', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11592, 5231236, NULL, NULL, NULL
    UNION ALL
    SELECT 'Oropéndola', 'Oriolus oriolus', 'fauna', 'Ave', 'Bosques de ribera,hileras de olmos,chopos,sotos,generalmente fluviales,parques,jardines...Mar-1600m', 'Protegida (LESRPE)', 'Ave de tamaño similar a un mirlo y llamativo color amarillento. El macho exhibe un intenso color amarillo limón en la cabeza — rayada con una línea ocular oscura— y en el cuerpo, que contrasta bastante con las anchas y redondeadas alas, totalmente negras, a excepción de dos parches amarillos a la altura de la articulación de la muñeca. La cola es igualmente amarilla, aunque presenta una ancha banda terminal negra. Posee patas de tono grisáceo y pico rojizo. La hembra, que recuerda a un pequeño pito real, muestra tonos más apagados que el macho, con partes superiores de color verde oliva e inferiores blanquecinas y rayadas en gris. Tiene las alas y la cola pardas, y el pico rojo sucio. Los jóvenes son casi iguales a las hembras, aunque con el pico pardo oscuro y el ojo negruzco. Se trata de un ave esquiva, por lo que la mayoría de las observaciones corresponden a individuos en vuelos breves entre la espesura. Su vuelo, directo y ondulado, alterna aleteos y alas plegadas, de modo similar al del pito real. Su carácter agresivo se evidencia en los frecuentes acosos a otras especies, incluso de mayor tamaño.', NULL, NULL, 'Abril a agosto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Oriole_2.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Oriolidae', 'Oriolus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11911, 2488949, NULL, NULL, NULL
    UNION ALL
    SELECT 'Gorrión chillón', 'Petronia petronia', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'El chillón es un gorrión grande y corpulento, con la cabeza robusta y el pico muy fuerte. En su plumaje dominan los tonos marróngrisáceos con un profuso listado oscuro en el dorso. Las partes inferiores, por el contrario, son claras y están adornadas con amplias listas de color gris parduzco. En la cabeza destacan tres listas anchas: una clara; otra marrón-grisácea tras el ojo bajo aquella, y, por encima, una parda oscura. Otra lista de color marrón pálido recorre el píleo. Bajo la garganta presenta una mancha amarilla que a menudo permanece oculta o poco visible. En la cola aparecen unas manchas blancas hacia los extremos, que resultan bien visibles en vuelo. No hay diferencias de coloración entre machos y hembras. Los jóvenes son difíciles de distinguir de los adultos, incluso recién volados del nido. Se diferencian de estos por carecer de la mancha amarilla en la garganta. Asimismo, el dibujo de la cara presenta en ellos un aspecto poco definido y su coloración general es más suave.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Petronia_petronia_-Ariege%2C_Midi-Pyrenee%2C_France-8-4c.jpg?width=1280', 'Petronia_petronia_-Ariege,_Midi-Pyrenee,_France-8.jpg: Sandra from … (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Passeridae', 'Petronia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11973, 2492350, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mirlo capiblanco', 'Turdus torquatus', 'fauna', 'Ave', 'Montaña con matorral y pastos; en paso, sierras con enebros y bayas', 'Protegida (LESRPE)', 'Mirlo de montaña que se distingue del común por una banda blanca en forma de media luna sobre el pecho y por las plumas del ala ribeteadas de claro, que dan un aspecto escamado. Es muy desconfiado y se aleja en cuanto detecta movimiento.', NULL, 'Media luna blanca en el pecho; Alas con aspecto escamado y plateado; Mucho más esquivo que el mirlo común', 'Paso migratorio e invernada en montaña', 'https://commons.wikimedia.org/wiki/Special:FilePath/2015-04-20_Turdus_torquatus_torquatus_Cairngorm_3.jpg?width=1280', 'MPF (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Turdidae', 'Turdus', 'LC (Preocupación menor) (evaluación UICN 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12324, 7865305, NULL, NULL, NULL
    UNION ALL
    SELECT 'Abubilla', 'Upupa epops', 'fauna', 'Ave', 'Campos abiertos, dehesas, cultivos con arbolado y bordes de matorral', 'Protegida (LESRPE)', 'Ave inconfundible de color canela con alas y cola a franjas blancas y negras, y una cresta eréctil que despliega en abanico al posarse. Sondea el suelo blando con el pico largo y curvo en busca de larvas e insectos. Su canto, un «up-up-up» sordo y repetido, se oye de lejos en primavera.', NULL, 'Vuelo ondulante y torpe, como una mariposa grande; Cresta que abre en abanico justo al aterrizar; Camina por el suelo clavando el pico largo y curvo', 'Todo el año en el sur peninsular; estival en el resto', 'https://commons.wikimedia.org/wiki/Special:FilePath/Wiedehopf_mit_Puppe_als_Futter.jpg?width=1280', 'Sven Damerow (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 3 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Upupa', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11211, 2498415, NULL, NULL, NULL
    UNION ALL
    SELECT 'Terrera común', 'Calandrella brachydactyla', 'fauna', 'Ave esteparia', 'Llanos de cultivo, eriales y pastizales rasos con suelo desnudo', 'Protegida (LESRPE)', 'Alondra pequeña y pálida de aspecto muy limpio, con el pecho sin apenas rayado salvo una mancha oscura a cada lado del cuello. Anida en el suelo, en cultivos y baldíos. En migración se agrupa en bandos que se levantan del suelo todos a la vez.', NULL, 'Mancha oscura a cada lado del cuello, como un botón; Pecho limpio, sin rayado extenso; Ceja clara y pico corto y grueso de granívora', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alondra.jpg?width=1280', 'Juan Lacruz (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Calandrella', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10734, 2490681, NULL, NULL, NULL
    UNION ALL
    SELECT 'Chotacabras cuellirrojo', 'Caprimulgus ruficollis', 'fauna', 'Ave', 'Matorral abierto, pinares aclarados, ramblas y caminos térreos', 'Protegida (LESRPE)', 'Ave crepuscular de plumaje jaspeado que imita la hojarasca, tan mimético que de día resulta casi imposible verla posada en el suelo. Caza polillas en vuelo con la boca muy abierta. Su canto nocturno es un «cu-toc, cu-toc» repetido de forma monótona durante minutos.', NULL, 'Collar rojizo en la nuca, más marcado que en su pariente europeo; Se levanta del camino al anochecer y vuelve a posarse unos metros más allá; Canto nocturno monótono, como un motor lejano', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Caprimulgus_ruficollis_-Portugal-8.jpg?width=1280', 'Olivença (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Caprimulgus', 'NT (Casi amenazado)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12122, 9411857, NULL, NULL, NULL
    UNION ALL
    SELECT 'Curruca tomillera', 'Curruca conspicillata', 'fauna', 'Ave', 'Matorral bajo y abierto, tomillares y saladares con arbustos dispersos', 'Protegida (LESRPE)', 'Curruca menuda de matorral raso, gris en la cabeza, parda en el dorso y con las plumas del ala ribeteadas de castaño encendido. El anillo blanco del ojo le da el aire de «gafas» que le da nombre. Es inquieta y suele delatarse por su reclamo antes de dejarse ver.', NULL, 'Anillo blanco alrededor del ojo bien marcado; Panel castaño vivo en el ala plegada; Vive en matorral muy bajo, no en arbolado', 'Todo el año en el sureste; parcialmente migradora', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fauvette_%C3%A0_lunettes_Aqueduc_de_Zaghouan.jpg?width=1280', 'El Golli Mohamed (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC (Preocupación menor)', 'Listado de Especies Silvestres en Régimen de Protección Especial (LESRPE)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 80923, 9868071, NULL, NULL, NULL
    UNION ALL
    SELECT 'Collalba rubia', 'Oenanthe hispanica', 'fauna', 'Ave', 'Laderas secas y pedregosas con matorral bajo y suelo desnudo', 'Protegida (LESRPE)', 'Collalba pequeña y contrastada: el macho es color arena claro con las alas negras y un antifaz o una garganta negros según la variedad. Como todas las collalbas, enseña al volar una cola blanca con una «T» negra invertida. Caza insectos lanzándose al suelo desde una piedra o una mata.', NULL, 'Cola blanca con una «T» negra al abrirse; Alas negras que resaltan sobre el cuerpo color arena; Se posa erguida en piedras y matas, muy visible', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Black-eared_Wheatear%2C_Punta_del_Sabinar%2C_Spain.jpg?width=1280', 'Vince Smith from London, United Kingdom (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Oenanthe', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11453, 5231235, NULL, NULL, NULL
    UNION ALL
    SELECT 'Acentor alpino', 'Prunella collaris', 'fauna', 'Ave', 'Roquedos y pedreras de alta montaña; en invierno baja a cortados', 'Protegida (LESRPE)', 'Pájaro robusto de montaña, pardo y discreto salvo por dos detalles: los flancos con listas castañas y una garganta blanca finamente moteada de negro. Camina entre las rocas buscando insectos y semillas, y en invierno desciende a cortados y construcciones.', NULL, 'Flancos con anchas listas castañas; Garganta blanca con motas negras, como un babero; Base del pico amarilla', 'Otoño e invierno en cotas bajas', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alpine_accentor_saganta.jpg?width=1280', 'Paco Gómez from Castellón, Spain (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 2 ocurrencias dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Prunellidae', 'Prunella', 'LC (Preocupación menor) (evaluación UICN 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11054, 5231770, NULL, NULL, NULL
    UNION ALL
    SELECT 'Alondra común', 'Alauda arvensis', 'fauna', 'Ave', NULL, 'LC', 'Aláudido típico, de tonos pardos y estriado oscuro, con pico fuerte, cuerpo alargado y robusto, patas, alas y cola alargadas, y hábitos terrestres. La especie combina la presencia de una pequeña cresta, una máscara facial pálida, pecho estriado, borde blanco terminal en las alas — como en la calandria— y rectrices externas de la cola blancas. Su vuelo es rápido, con intenso batido de alas. Tiene una gran capacidad de maniobra en el aire, con posibilidades de cernidos prolongados y ascensiones y descensos vertiginosos .', 'EIDOS (IEPNB, MITECO), v_atributos_pliniancore, atributo «Descripción de la especie»', NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alauda_arvensis_2.jpg?width=1280', 'Daniel Pettersson (CC BY-SA 2.5 se) · Wikimedia Commons', NULL, NULL, 1, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía; sin figura de protección en la vista de normas', 'Chordata', 'Aves', 'Passeriformes', 'Alaudidae', 'Alauda', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10768, 8077224, NULL, NULL, NULL
    UNION ALL
    SELECT 'Águila calzada', 'Hieraaetus pennatus', 'fauna', 'Ave rapaz', 'Bosques y sierras con arbolado, cazando sobre zonas abiertas cercanas', 'Protegida (LESRPE)', 'Águila pequeña, del tamaño de un ratonero, con dos formas de plumaje muy distintas: una clara con el vientre blanco y otra oscura y uniforme. Nidifica en árboles dentro del bosque y caza en campo abierto lanzándose desde altura. Se identifica en vuelo por las «luces de posición»: dos manchas blancas en el arranque de las alas.', NULL, 'Dos manchas blancas donde el ala se une al cuerpo; Existen ejemplares claros y oscuros de la misma especie; Cola larga y recta, sin la muesca del milano', 'Primavera y verano (estival); algunos ejemplares invernan', 'https://commons.wikimedia.org/wiki/Special:FilePath/Booted_eagle%2C_Hieraaetus_pennatus%2C_at_Kgalagadi_Transfrontier_Pa_(32334023348).jpg?width=1280', 'Derek Keats from Johannesburg, South Africa (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', NULL, NULL, 'Hieraaetus', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000); LESRPE', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11959, 2480685, NULL, NULL, NULL
    UNION ALL
    SELECT 'Alcaudón real', 'Lanius meridionalis', 'fauna', 'Ave', 'Campo abierto con matorral disperso, cables y posaderos altos', 'Protegida (LESRPE)', 'Alcaudón grande, gris por encima y con un antifaz negro que le cruza el ojo. Caza al acecho desde un posadero alto y tiene la costumbre de empalar sus presas —insectos, lagartijas, ratones— en espinas y alambres, formando pequeñas despensas.', NULL, 'Antifaz negro sobre fondo gris claro; Siempre en lo alto de un cable, poste o mata; Presas empaladas en espinos cerca de su territorio', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/S%C3%BCdlicher-Raubw%C3%BCrger_2018-01-07_0003.jpg?width=1280', 'Andreas Trepte (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Laniidae', 'Lanius', 'VU (Vulnerable) (evaluación UICN 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011); UICN España: NT (Casi amenazado) (2004)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 16426, 7341500, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ruiseñor común', 'Luscinia megarhynchos', 'fauna', 'Ave', 'Pisos bioclimáticos termo,meso,supramediterráneos,matorrales,sotos densos,montes bajos, jardines...', 'Protegida (LESRPE)', 'Ave estilizada, de pico fino y cola larga. Hembras y machos son iguales. Su manto y sus alas presentan un color pardo ocráceo uniforme, excepto en la cola, que posee un distintivo tono pardo rojizo. Las partes inferiores, mucho más claras, tienen color blanco crema. Este pájaro, muy escondidizo, rara vez abandona la protección de la espesura de la vegetación, pero resulta muy fácil de detectar por su inconfundible canto, muy sonoro, emitido incansablemente durante el día y la noche. Los jóvenes volantones, previamente a la muda parcial de su plumaje que tiene lugar antes de que comience la migración, exhiben un plumaje pardo que muestra plumas manchadas en su extremo con motas amarillentas. Los adultos se pueden confundir con carriceros comunes y ruiseñores bastardos, con los que a veces conviven en malezas ribereñas. Sin embargo, los carriceros presentan un tono ocre más pálido y amarillento, y carecen de la cola rojiza que luce el ruiseñor común. Lo mismo sucede con el ruiseñor bastardo, que además tiene una conspicua línea blanca sobre el ojo y posee unas alas y una cola cortas y redondeadas.', NULL, NULL, 'Abril a septiembre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Luscinia_megarhynchos_-_01.jpg?width=1280', 'Carlos Delgado (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Luscinia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11701, 7660710, NULL, NULL, NULL
    UNION ALL
    SELECT 'Collalba gris', 'Oenanthe oenanthe', 'fauna', 'Ave', 'Pastizales pedregosos, canchales y zonas abiertas de montaña', 'Protegida (LESRPE)', 'Collalba de dorso gris en el macho, con antifaz negro y alas oscuras. Como todas las collalbas, delata su identidad al volar: obispillo blanco y cola blanca con una «T» negra invertida. Se posa erguida en piedras y hace carreras cortas por el suelo.', NULL, 'Obispillo blanco y «T» negra en la cola; Macho con antifaz negro y dorso gris; Carreras cortas por el suelo entre piedra y piedra', 'Paso migratorio y cría en montaña', 'https://commons.wikimedia.org/wiki/Special:FilePath/Oenanthe_oenanthe_Larvik.JPG?width=1280', 'Arnstein Rønning (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Muscicapidae', 'Oenanthe', 'LC (Preocupación menor) (evaluación UICN 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11890, 5231240, NULL, NULL, NULL
    UNION ALL
    SELECT 'Mosquitero musical', 'Phylloscopus trochilus', 'fauna', 'Ave', 'Bosques abiertos de frondosas, robledales, hayedos,castañares,arbustos,a media altura, media altura..', 'Protegida (LESRPE)', 'Presenta gran parecido con otros congéneres, especialmente los mosquiteros común e ibérico, de los que se diferencia por poseer el pico y las patas pálidos, las listas faciales más marcadas —con una lista superciliar muy patente—, las partes inferiores más amarillas y el dorso de un tono verdoso más brillante.', NULL, NULL, 'Marzo, abril, mayo, agosto, septiembre, octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Willow_Warbler_Phylloscopus_trochilus.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Phylloscopidae', 'Phylloscopus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 12337, 2493052, NULL, NULL, NULL
    UNION ALL
    SELECT 'Acentor común', 'Prunella modularis', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Pájaro del tamaño de un gorrión común, con el pico fino y puntiagudo, y las patas fuertes y rojizas. De comportamiento huidizo, le gusta moverse entre la vegetación baja y caminar por el suelo. Tiene las partes superiores del plumaje marrones y con escamado pardo oscuro, semejantes al dorso de un gorrión común. La cabeza, la garganta y el pecho son de un color gris plomizo, más intenso en los machos, con la zona auricular y el píleo marrones. Las partes posteriores del vientre poseen un tono gris más claro, con los flancos marrones. Los jóvenes exhiben cabeza y garganta de color castaño, en lugar de gris, y muestran todo el plumaje fuertemente listado de pardo oscuro. La base de su pico es naranja amarillenta, mientras que los adultos presentan todo el pico negro.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Acentor_com%C3%BAn23_by_Paco_G%C3%B3mez.jpg?width=1280', 'Paco Gómez (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Prunellidae', 'Prunella', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 11761, 5231763, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lúgano', 'Spinus spinus', 'fauna', 'Ave', 'Sus preferencias de hábitat van ligadas a sus requerimientos tróficos', 'Protegida (LESRPE)', 'Se trata de un ave pequeña, de pico corto y fino, que muestra cola corta y escotada cuando está cerrada. Su coloración puede recordar a la de verdecillos, verderones comunes y verderones serranos. Pero los lúganos se distinguen bien por la combinación de los siguientes caracteres: pequeño tamaño, manchas amarillas en alas y cola, y franjas amarillas en los “hombros” de las alas. Además, los machos tienen el capirote y la garganta negros. Es una especie gregaria que se mezcla con otras, sobre todo fringílidos como pardillos, pinzones vulgares, verdecillos, verderones serranos, pinzones reales, etc. Pero, a diferencia de la mayoría de los fringílidos, el lúgano también busca alimento en las ramas de árboles de ribera, siendo común observarlo en alisos, olmos y abedules.', NULL, NULL, 'Octubre a abril', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carduelis_Spinus_(55339970).jpeg?width=1280', 'Kobolt (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha, que la cita como «Carduelis spinus» (el backbone de GBIF lo trata como sinónimo de Spinus spinus); EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Fringillidae', 'Spinus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2017)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 33009, 6092830, NULL, NULL, NULL
    UNION ALL
    SELECT 'Curruca capirotada', 'Sylvia atricapilla', 'fauna', 'Ave', NULL, 'Protegida (LESRPE)', 'Curruca de mediano tamaño, de aspecto más compacto y robusto que la mayor parte de sus congéneres, aunque muy similar en tamaño y silueta a la curruca mosquitera. Al igual que ésta, y a diferencia de la mayoría de las currucas, no presenta ni rectrices externas ni garganta blanquecinas. Luce una tonalidad general grisácea, aunque la hembra muestra en las alas y en las regiones ventrales tintes más pardo rojizos. Los machos poseen el capirote negro, mientras que las hembras y los jóvenes lo tienen de color castaño.', NULL, NULL, 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sylvia_atricapilla_-Lullington_Heath%2C_East_Sussex%2C_England_-male-8.jpg?width=1280', 'Ron Knight from Seaford, East Sussex, United Kingdom (CC BY 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Sylvia', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2016)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', NULL, 10791, 2492956, NULL, NULL, NULL
    UNION ALL
    SELECT 'Curruca zarcera', 'Curruca communis', 'fauna', 'Ave', 'Linderos con arbustos y malezas espesas,cultivos, bosquetes, praderas y claros con setos de matorral', 'Protegida (LESRPE)', 'Curruca de mediano tamaño, de cola relativamente larga y con rectrices externas blancas. El macho presenta el dorso de color pardo, con la cabeza gris en plumaje de cría y parda durante el resto del año, las alas pardo-rojizas, la garganta blanca, y las partes inferiores blanquecinas y con tonos rosados. La hembra muestra tonalidades más apagadas, con la cabeza y el dorso más pardos, la garganta blanquecina y más apagada, y la zona ventral también blanquecina y sin los tonos ligeramente asalmonados del macho. Ambos sexos tienen las patas claras. Los adultos lucen un iris rojizo, que contrasta con un tenue anillo orbital claro.', NULL, NULL, 'Abril a octubre', 'https://commons.wikimedia.org/wiki/Special:FilePath/Flickr_-_Rainbirder_-_Common_Whitethroat_(Sylvia_communis).jpg?width=1280', 'Steve Garvie from Dunfermline, Fife, Scotland (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'GBIF: 1 ocurrencia dentro del espacio (barrido de 2026-08-15); las aves no se adscriben a hábitats; Decreto n.º 28/2025, de 10 de abril, Plan de gestión integral del Altiplano, volumen III §2.2 (PRUG del Parque Regional «Sierra del Carche»), BORM n.º 103, de 6 de mayo de 2025: la norma la enumera en el inventario de especies del propio Parque Regional, que es el espacio de esta ficha; EIDOS (IEPNB, MITECO) para la taxonomía y el estado legal', 'Chordata', 'Aves', 'Passeriformes', 'Sylviidae', 'Curruca', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero)', 'No incluida en el Catálogo Regional de especies protegidas (Región de Murcia)', 'Fichada hasta el 2026-08-17 como «Sylvia communis», que EIDOS da por sinónimo. taxonid 80921: «Sylvia communis Latham, 1787» es Sinónimo y «Curruca communis (Latham, 1787)» Aceptado/válido. Se adopta el nombre aceptado; la gbifSpeciesKey NO cambia porque el backbone de GBIF acepta el nombre anterior y es esa key la que lleva las ocurrencias.', 80921, 2492943, NULL, NULL, NULL
) s WHERE pk.slug = 'sierra-de-el-carche'
ON DUPLICATE KEY UPDATE
    common_name = VALUES(common_name),
    kingdom = VALUES(kingdom),
    family = VALUES(family),
    primary_habitat = VALUES(primary_habitat),
    conservation_status = VALUES(conservation_status),
    description = VALUES(description),
    description_source = VALUES(description_source),
